            acc = 0.0
            for rr, cc, w in taps:
                product = snapshot[rr * W + cc] * w
                if not math.isfinite(product):
                    raise ValueError(
                        "bilinear_resize2d intermediate must be finite"
                    )
                acc += product
                if not math.isfinite(acc):
                    raise ValueError(
                        "bilinear_resize2d intermediate must be finite"
                    )
            out_data.append(acc)
    if not self.requires_grad:
